const body = $json.body ?? {};
const stage = body.approval_stage;
const decision = body.decision || 'approved';
if (!['analysis','plan','final_delivery'].includes(stage)) {
  throw new Error('Invalid approval_stage');
}
if (!['approved','revision_requested','rejected'].includes(decision)) {
  throw new Error('Invalid decision');
}
const payload = {
  ...body,
  decision,
  reviewer_type: 'human',
  reviewer_id: 'human:' + (body.reviewer_name || body.reviewer_id || 'operator')
};
return [{json: {...payload, payload_sql: JSON.stringify(payload).replace(/'/g, "''")}}];
